using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;using Cis.Abstractions;
namespace Cis.Modules.Learn;
public sealed record LearningCollection(string CollectedAtUtc,string Digest,int ToolRecords,int FailedTools,int DiagnosticErrors,int DiagnosticWarnings,IReadOnlyList<string>Evidence);
public sealed record LearningProposal(string Id,string Status,string SourceDigest,string Title,string Recommendation,string Path,string?Reviewer,string?Rationale,string?ReviewedAtUtc,string?AppliedAtUtc);
public sealed record LearnResult(string Status,string?RepositoryPath,LearningCollection?Collection,IReadOnlyList<LearningProposal>Proposals,IReadOnlyList<string>History,IReadOnlyList<string>Errors,bool Applied){public int ExitCode=>Errors.Count>0?4:0;}
public sealed class LearnService
{public const string RootPath=".cis/local/learn";private static readonly JsonSerializerOptions J=new(JsonSerializerDefaults.Web){WriteIndented=true};private readonly ICisRepositoryContextResolver _resolver;private readonly Func<DateTimeOffset>_clock;public LearnService(ICisRepositoryContextResolver r,Func<DateTimeOffset>?c=null){_resolver=r;_clock=c??(()=>DateTimeOffset.UtcNow);}
 public LearnResult Collect(string repo){var c=Resolve(repo,out var e);if(c is null)return New(null,"invalid-repository",null,[],e,false);var evidence=new List<string>();var tools=Find(c,".cis/local/feedback/tool-usage.jsonl");var records=File.Exists(tools)?File.ReadLines(tools).Where(x=>!string.IsNullOrWhiteSpace(x)).ToArray():[];var failed=records.Count(x=>x.Contains("failed",StringComparison.OrdinalIgnoreCase)||x.Contains("exitCode\":4",StringComparison.OrdinalIgnoreCase));if(File.Exists(tools))evidence.Add(".cis/local/feedback/tool-usage.jsonl");var diagnostics=Find(c,".cis/local/diagnostics/analysis.json");var errors=0;var warnings=0;if(File.Exists(diagnostics)){var text=File.ReadAllText(diagnostics);errors=Count(text,"error");warnings=Count(text,"warning");evidence.Add(".cis/local/diagnostics/analysis.json");}var digest=Sha(string.Join("\n",evidence.Select(x=>x+":"+Sha(File.ReadAllText(Find(c,x))))));var collection=new LearningCollection(_clock().ToUniversalTime().ToString("O"),digest,records.Length,failed,errors,warnings,evidence);var path=Find(c,RootPath+"/collection.json");Directory.CreateDirectory(Path.GetDirectoryName(path)!);Write(path,JsonSerializer.Serialize(collection,J));return New(c,"collected",collection,ReadProposals(c),[],true);}
 public LearnResult Propose(string repo){var c=Resolve(repo,out var e);if(c is null)return New(null,"invalid-repository",null,[],e,false);var collection=ReadCollection(c,e);if(collection is null)return New(c,"missing-collection",null,ReadProposals(c),e,false);var proposals=ReadProposals(c).ToList();var recommendations=new List<(string,string)>();if(collection.FailedTools>0)recommendations.Add(("Reduce repeated tool failures","Add or refine a deterministic preflight/doctor rule for the repeated failure evidence before agents execute the affected command."));if(collection.DiagnosticErrors>0)recommendations.Add(("Promote runtime failures into verification","Add a bounded verification check that covers the recurring diagnostic error pattern and its operational evidence."));if(collection.ToolRecords>0&&recommendations.Count==0)recommendations.Add(("Compact successful routing output","Review high-volume tool output and prefer the existing agent/JSON projection where it saves context without removing evidence."));if(recommendations.Count==0)return New(c,"no-opportunities",collection,proposals,[],false);foreach(var item in recommendations){if(proposals.Any(x=>x.SourceDigest==collection.Digest&&x.Title==item.Item1))continue;var id=$"CIS-LEARN-{proposals.Count+1:0000}";var path=Find(c,$"{RootPath}/proposals/{id}.md");Directory.CreateDirectory(Path.GetDirectoryName(path)!);var markdown=Render(new(id,"Proposed",collection.Digest,item.Item1,item.Item2,Relative(c,path),null,null,null,null));Write(path,markdown);proposals.Add(Parse(path)!);}return New(c,"proposed",collection,proposals,[],true);}
 public LearnResult Review(string repo,string id,string decision,string reviewer,string rationale){var c=Resolve(repo,out var e);if(c is null)return New(null,"invalid-repository",null,[],e,false);if(decision is not("approve"or"reject"))e.Add("Decision must be approve or reject.");if(string.IsNullOrWhiteSpace(reviewer)||string.IsNullOrWhiteSpace(rationale))e.Add("Reviewer and rationale are required.");var p=FindProposal(c,id,e);if(p is null||e.Count>0)return New(c,"invalid",ReadCollection(c,new()),ReadProposals(c),e,false);if(p.Status is not "Proposed")e.Add("Only a Proposed learning item can be reviewed.");if(e.Count>0)return New(c,"invalid",ReadCollection(c,new()),ReadProposals(c),e,false);var updated=p with{Status=decision=="approve"?"Approved":"Rejected",Reviewer=reviewer.Trim(),Rationale=rationale.Trim(),ReviewedAtUtc=_clock().ToUniversalTime().ToString("O")};Write(Find(c,p.Path),Render(updated));return New(c,"reviewed",ReadCollection(c,new()),ReadProposals(c),[],true);}
 public LearnResult Apply(string repo,string id){var c=Resolve(repo,out var e);if(c is null)return New(null,"invalid-repository",null,[],e,false);var p=FindProposal(c,id,e);if(p is null)return New(c,"invalid",ReadCollection(c,new()),ReadProposals(c),e,false);if(p.Status!="Approved")e.Add("Learning proposal must be human-approved before application.");if(e.Count>0)return New(c,"blocked",ReadCollection(c,new()),ReadProposals(c),e,false);var at=_clock().ToUniversalTime().ToString("O");var updated=p with{Status="Applied",AppliedAtUtc=at};Write(Find(c,p.Path),Render(updated));var history=Path.Combine(c.DocumentationPath,"references","learning-history.md");if(!File.Exists(history))Write(history,"---\ntitle: \"Governed Learning History\"\ntype: learning-history\nstatus: Active\nowner: \"Repository maintainers\"\nlast_reviewed: \"2026-08-14\"\nreview_cadence: \"on learning application\"\n---\n\n# Governed learning history\n\n| Applied UTC | Proposal | Recommendation | Reviewer | Rationale | Source digest |\n|---|---|---|---|---|---|\n");File.AppendAllText(history,$"| {at} | {p.Id} | {Esc(p.Recommendation)} | {Esc(p.Reviewer)} | {Esc(p.Rationale)} | `{p.SourceDigest}` |\n");return New(c,"applied",ReadCollection(c,new()),ReadProposals(c),ReadHistory(history),true);}
 public LearnResult History(string repo){var c=Resolve(repo,out var e);if(c is null)return New(null,"invalid-repository",null,[],e,false);var h=Path.Combine(c.DocumentationPath,"references","learning-history.md");return New(c,"available",ReadCollection(c,new()),ReadProposals(c),ReadHistory(h),false);}
 private static string Render(LearningProposal p)=>$"---\nlearning_id: {p.Id}\nstatus: {p.Status}\nsource_digest: {p.SourceDigest}\ntitle: \"{Esc(p.Title)}\"\nreviewer: \"{Esc(p.Reviewer)}\"\nrationale: \"{Esc(p.Rationale)}\"\nreviewed_at_utc: \"{p.ReviewedAtUtc??""}\"\napplied_at_utc: \"{p.AppliedAtUtc??""}\"\n---\n\n# {p.Title}\n\n## Recommendation\n\n{p.Recommendation}\n\n## Authority\n\nThis derived proposal cannot modify code, policy, approval, or acceptance. `cis learn review` requires a human, and `cis learn apply` only promotes the approved recommendation into canonical learning history.\n";
 private static LearningProposal?Parse(string path){var t=File.ReadAllText(path);string V(string k)=>Regex.Match(t,$"(?m)^{k}:\\s*[\"']?(?<v>[^\"'\\r\\n]*)").Groups["v"].Value.Trim();var id=V("learning_id");if(id.Length==0)return null;var title=V("title");var recommendation=Regex.Match(t,@"(?s)## Recommendation\s+(?<v>.*?)(?:\n## |\z)").Groups["v"].Value.Trim();return new(id,V("status"),V("source_digest"),title,recommendation,path.Replace('\\','/'),Null(V("reviewer")),Null(V("rationale")),Null(V("reviewed_at_utc")),Null(V("applied_at_utc")));}
 private static string?Null(string x)=>x.Length==0?null:x;private static LearningProposal?FindProposal(CisRepositoryContext c,string id,List<string>e){var p=ReadProposals(c).FirstOrDefault(x=>x.Id.Equals(id,StringComparison.OrdinalIgnoreCase));if(p is null)e.Add($"Unknown learning proposal '{id}'.");return p;}private static IReadOnlyList<LearningProposal>ReadProposals(CisRepositoryContext c){var root=Find(c,RootPath+"/proposals");if(!Directory.Exists(root))return[];return Directory.EnumerateFiles(root,"*.md").Select(Parse).Where(x=>x is not null).Cast<LearningProposal>().Select(x=>x with{Path=Relative(c,Path.GetFullPath(x.Path))}).OrderBy(x=>x.Id,StringComparer.Ordinal).ToArray();}private static LearningCollection?ReadCollection(CisRepositoryContext c,List<string>e){var p=Find(c,RootPath+"/collection.json");if(!File.Exists(p)){e.Add("Run `cis learn collect` first.");return null;}try{return JsonSerializer.Deserialize<LearningCollection>(File.ReadAllText(p),J);}catch(JsonException x){e.Add(x.Message);return null;}}private static int Count(string json,string key){try{using var d=JsonDocument.Parse(json);return d.RootElement.TryGetProperty("counts",out var c)&&c.TryGetProperty(key,out var v)?v.GetInt32():0;}catch(JsonException){return 0;}}private static IReadOnlyList<string>ReadHistory(string p)=>File.Exists(p)?File.ReadLines(p).Where(x=>x.StartsWith('|')&&!x.Contains("---")).ToArray():[];private CisRepositoryContext?Resolve(string p,out List<string>e){var r=_resolver.Resolve(p);e=r.Errors.ToList();return r.Context;}private static string Find(CisRepositoryContext c,string p)=>Path.Combine(c.RepositoryPath,p.Replace('/',Path.DirectorySeparatorChar));private static string Relative(CisRepositoryContext c,string p)=>Path.GetRelativePath(c.RepositoryPath,p).Replace(Path.DirectorySeparatorChar,'/');private static string Sha(string x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x))).ToLowerInvariant();private static string Esc(string?x)=>(x??"").Replace('|','/').Replace('"','\'').Replace('\r',' ').Replace('\n',' ').Trim();private static void Write(string p,string x){Directory.CreateDirectory(Path.GetDirectoryName(p)!);var t=p+".tmp";File.WriteAllText(t,x);File.Move(t,p,true);}private static LearnResult New(CisRepositoryContext?c,string s,LearningCollection?x,IReadOnlyList<LearningProposal>p,IReadOnlyList<string>h,bool a)=>new(s,c?.RepositoryPath,x,p,h,[],a);private static LearnResult New(CisRepositoryContext?c,string s,LearningCollection?x,IReadOnlyList<LearningProposal>p,List<string>e,bool a)=>new(s,c?.RepositoryPath,x,p,[],e,a);}
